head.b:skin:
/* ═══════════════════════════════════════════════════════════════
   CYBERBIVASH® — SENTINEL APEX BLOGGER THEME v22.0
   Production | Google Discover + News + E-E-A-T Optimized
   ═══════════════════════════════════════════════════════════════ */
:root {
  --void: #06080d;
  --deep: #080c15;
  --surface: #0f1521;
  --card: #111827;
  --card2: #0d1420;
  --border: #1e293b;
  --border2: #243044;
  --accent: #00e5c3;
  --accent2: #0ea5e9;
  --accent3: #f59e0b;
  --accent4: #8b5cf6;
  --danger: #ef4444;
  --success: #22c55e;
  --accent-dim: rgba(0,229,195,0.10);
  --accent2-dim: rgba(14,165,233,0.10);
  --text-primary: #ffffff;
  --text-secondary: #94a3b8;
  --text-muted: #475569;
  --glow: 0 0 30px rgba(0,229,195,0.18);
  --glow2: 0 0 30px rgba(14,165,233,0.18);
  --radius: 12px;
  --radius-sm: 6px;
}
*{box-sizing:border-box;margin:0;padding:0;}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;}
body{font-family:'Inter',sans-serif;background:var(--void);color:var(--text-secondary);line-height:1.8;overflow-x:hidden;}
a{color:inherit;text-decoration:none;}
img{max-width:100%;height:auto;display:block;}
button{cursor:pointer;border:none;background:none;font-family:inherit;}

/* ── READING PROGRESS BAR ─────────────────────────────── */
#reading-progress{position:fixed;top:0;left:0;height:3px;background:linear-gradient(90deg,var(--accent),var(--accent2),var(--accent4));width:0%;z-index:9999;transition:width 0.1s linear;}

/* ── SKIP NAV (Accessibility) ─────────────────────────── */
.skip-nav{position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;}
.skip-nav:focus{position:fixed;top:0;left:0;width:auto;height:auto;padding:12px 20px;background:var(--accent);color:#000;font-weight:700;z-index:10000;font-size:14px;}

/* ── TICKER ──────────────────────────────────────────── */
.cdb-ticker{background:linear-gradient(90deg,#000 0%,#060d18 100%);border-bottom:1px solid var(--border);padding:8px 0;overflow:hidden;position:relative;z-index:200;}
.ticker-inner{display:flex;align-items:center;gap:0;}
.ticker-label{background:var(--accent);color:#000;font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:900;letter-spacing:2px;padding:4px 14px;white-space:nowrap;flex-shrink:0;text-transform:uppercase;}
.ticker-track{overflow:hidden;flex:1;}
.ticker-content{display:inline-flex;gap:40px;animation:tickerScroll 45s linear infinite;white-space:nowrap;padding-left:40px;}
.ticker-content:hover{animation-play-state:paused;}
.ticker-item{color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:11px;display:inline-flex;align-items:center;gap:8px;}
.ticker-badge{font-size:9px;padding:2px 6px;border-radius:3px;font-weight:900;letter-spacing:1px;text-transform:uppercase;}
.ticker-badge.crit{background:var(--danger);color:#fff;}
.ticker-badge.warn{background:var(--accent3);color:#000;}
.ticker-badge.info{background:var(--accent2);color:#fff;}
.ticker-badge.zero{background:var(--accent4);color:#fff;}
.ticker-badge.live{background:var(--accent);color:#000;}
.ticker-item a{color:#fff;font-weight:600;}
.ticker-item a:hover{color:var(--accent);}
@keyframes tickerScroll{0%{transform:translateX(0);}100%{transform:translateX(-50%);}}

/* ── TOP NAV ──────────────────────────────────────────── */
.cdb-topnav{background:rgba(6,8,13,0.97);border-bottom:1px solid var(--border);padding:0 24px;position:sticky;top:0;z-index:999;backdrop-filter:blur(12px);-webkit-backdrop-filter:blur(12px);}
.topnav-inner{max-width:1450px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;height:54px;gap:16px;}
.nav-logo{display:flex;align-items:center;gap:10px;flex-shrink:0;}
.nav-logo-icon{width:32px;height:32px;border:1.5px solid var(--accent);border-radius:6px;display:flex;align-items:center;justify-content:center;background:var(--surface);font-size:16px;}
.nav-logo-text{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:15px;letter-spacing:1px;}
.nav-logo-text span{color:var(--accent);}
.nav-logo-sub{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:2px;text-transform:uppercase;display:block;line-height:1;}
.nav-links{display:flex;align-items:center;gap:2px;flex:1;justify-content:center;}
.nav-link{color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:6px 10px;border-radius:4px;transition:all 0.2s;white-space:nowrap;border:1px solid transparent;}
.nav-link:hover{color:var(--accent);border-color:var(--border);background:var(--accent-dim);}
.nav-link.active,.nav-link[aria-current='page']{color:var(--accent);border-color:var(--accent-dim);background:var(--accent-dim);}
.nav-link.highlight{color:#000;background:var(--accent);border-color:var(--accent);}
.nav-link.highlight:hover{background:#00ffdc;box-shadow:0 0 16px rgba(0,229,195,0.4);}
.nav-link.api-link{color:var(--accent2);border-color:rgba(14,165,233,0.2);}
.nav-link.api-link:hover{background:var(--accent2-dim);color:#fff;}
.nav-cta-group{display:flex;align-items:center;gap:8px;flex-shrink:0;}
.nav-status-dot{width:7px;height:7px;background:var(--success);border-radius:50%;animation:pulseDot 2s infinite;flex-shrink:0;}
@keyframes pulseDot{0%,100%{box-shadow:0 0 0 0 rgba(34,197,94,0.5);}50%{box-shadow:0 0 0 5px rgba(34,197,94,0);}}

/* ── HAMBURGER ────────────────────────────────────────── */
.nav-hamburger{display:none;flex-direction:column;gap:5px;cursor:pointer;padding:8px;border:1px solid var(--border);border-radius:6px;background:none;aria-label:'Menu';}
.nav-hamburger span{display:block;width:20px;height:2px;background:var(--text-secondary);transition:0.3s;}
.nav-hamburger.open span:nth-child(1){transform:translateY(7px) rotate(45deg);}
.nav-hamburger.open span:nth-child(2){opacity:0;}
.nav-hamburger.open span:nth-child(3){transform:translateY(-7px) rotate(-45deg);}
.mobile-menu{display:none;background:var(--deep);border-bottom:1px solid var(--border);padding:20px 24px;}
.mobile-menu.open{display:block;}
.mobile-menu-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:16px;}
.mobile-menu-link{color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:11px;font-weight:700;letter-spacing:1px;padding:10px 14px;border:1px solid var(--border);border-radius:6px;text-transform:uppercase;transition:0.2s;display:block;text-align:center;}
.mobile-menu-link:hover{color:var(--accent);border-color:var(--accent-dim);background:var(--accent-dim);}
.mobile-menu-link.mm-upgrade{background:var(--accent);color:#000;border-color:var(--accent);}

/* ── BREADCRUMB ───────────────────────────────────────── */
.cdb-breadcrumb{background:var(--deep);border-bottom:1px solid var(--border);padding:10px 24px;}
.breadcrumb-inner{max-width:1450px;margin:0 auto;display:flex;align-items:center;gap:8px;font-family:'JetBrains Mono',monospace;font-size:11px;color:var(--text-muted);flex-wrap:wrap;}
.breadcrumb-inner a{color:var(--text-secondary);transition:0.2s;}
.breadcrumb-inner a:hover{color:var(--accent);}
.breadcrumb-sep{opacity:0.4;}
.breadcrumb-current{color:var(--accent);}

/* ── HERO ─────────────────────────────────────────────── */
.cdb-hero{background:linear-gradient(135deg,#06080d 0%,#0a0e1a 40%,#060d18 100%);border-bottom:1px solid var(--border);padding:60px 24px 50px;position:relative;overflow:hidden;}
.hero-bg-grid{position:absolute;inset:0;background-image:linear-gradient(var(--border) 1px,transparent 1px),linear-gradient(90deg,var(--border) 1px,transparent 1px);background-size:60px 60px;opacity:0.15;pointer-events:none;}
.hero-bg-glow{position:absolute;top:-100px;left:50%;transform:translateX(-50%);width:700px;height:500px;background:radial-gradient(ellipse,rgba(0,229,195,0.06) 0%,transparent 70%);pointer-events:none;}
.hero-inner{max-width:1200px;margin:0 auto;position:relative;text-align:center;}
.hero-badge{display:inline-flex;align-items:center;gap:8px;border:1px solid var(--border2);background:rgba(0,229,195,0.06);border-radius:20px;padding:5px 16px;margin-bottom:24px;}
.hero-badge-dot{width:6px;height:6px;background:var(--accent);border-radius:50%;animation:pulseDot 2s infinite;}
.hero-badge-text{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;}
.hero-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:clamp(26px,4vw,52px);line-height:1.1;letter-spacing:-1px;margin-bottom:16px;}
.hero-title span{color:var(--accent);}
.hero-subtitle{color:var(--text-secondary);font-size:16px;max-width:700px;margin:0 auto 36px;line-height:1.7;}
.hero-cta-row{display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;margin-bottom:48px;}
.hero-btn{display:inline-flex;align-items:center;gap:8px;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:12px;letter-spacing:1px;text-transform:uppercase;padding:14px 24px;border-radius:6px;transition:all 0.3s;border:1px solid;}
.hero-btn-primary{background:var(--accent);color:#000;border-color:var(--accent);}
.hero-btn-primary:hover{background:#00ffdc;box-shadow:0 0 30px rgba(0,229,195,0.5);transform:translateY(-2px);}
.hero-btn-secondary{background:transparent;color:var(--accent2);border-color:rgba(14,165,233,0.3);}
.hero-btn-secondary:hover{background:var(--accent2-dim);border-color:var(--accent2);transform:translateY(-2px);}
.hero-btn-ghost{background:transparent;color:var(--text-secondary);border-color:var(--border);}
.hero-btn-ghost:hover{color:#fff;border-color:var(--text-secondary);}
.hero-stats-row{display:flex;align-items:center;justify-content:center;gap:32px;flex-wrap:wrap;border-top:1px solid var(--border);padding-top:28px;}
.hero-stat{text-align:center;}
.hero-stat-num{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:22px;}
.hero-stat-label{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;text-transform:uppercase;margin-top:4px;}

/* ── PLATFORM CARDS ───────────────────────────────────── */
.platform-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:12px;max-width:1100px;margin:0 auto 48px;}
.platform-card{background:var(--card);border:1px solid var(--border);border-radius:10px;padding:16px 14px;text-align:left;transition:all 0.3s;display:block;position:relative;overflow:hidden;}
.platform-card:hover{transform:translateY(-4px);border-color:var(--accent);box-shadow:var(--glow);}
.platform-card.blue:hover{border-color:var(--accent2);box-shadow:var(--glow2);}
.platform-card.amber:hover{border-color:var(--accent3);box-shadow:0 0 30px rgba(245,158,11,0.18);}
.platform-card.purple:hover{border-color:var(--accent4);box-shadow:0 0 30px rgba(139,92,246,0.18);}
.pc-icon{font-size:22px;margin-bottom:10px;display:block;}
.pc-name{color:#fff;font-family:'Outfit',sans-serif;font-weight:700;font-size:13px;margin-bottom:4px;}
.pc-desc{color:var(--text-muted);font-size:11px;line-height:1.5;}
.pc-tag{display:inline-block;margin-top:8px;color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:1px;text-transform:uppercase;border:1px solid var(--accent-dim);padding:2px 7px;border-radius:3px;}
.pc-tag.blue{color:var(--accent2);border-color:rgba(14,165,233,0.2);}
.pc-tag.amber{color:var(--accent3);border-color:rgba(245,158,11,0.2);}
.pc-tag.purple{color:var(--accent4);border-color:rgba(139,92,246,0.2);}

/* ── LIVE INTEL BANNER ────────────────────────────────── */
.live-intel-banner{background:linear-gradient(135deg,#06080d,#0a0f1e);border:1px solid var(--border2);border-radius:14px;padding:28px;margin-bottom:30px;position:relative;overflow:hidden;}
.live-intel-banner::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--accent),var(--accent2),var(--accent4));}
.lib-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;flex-wrap:wrap;gap:10px;}
.lib-title{color:#fff;font-family:'JetBrains Mono',monospace;font-weight:900;font-size:11px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:8px;}
.lib-live{color:var(--accent);font-size:9px;animation:blink 1.5s infinite;}
@keyframes blink{0%,100%{opacity:1;}50%{opacity:0.3;}}
.lib-cta{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;border:1px solid var(--accent-dim);padding:6px 14px;border-radius:4px;transition:0.3s;}
.lib-cta:hover{background:var(--accent-dim);color:#fff;}
.lib-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;}
.lib-item{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:14px;transition:0.3s;}
.lib-item:hover{border-color:var(--accent);background:rgba(0,229,195,0.04);}
.lib-item-label{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:2px;text-transform:uppercase;margin-bottom:6px;}
.lib-item.blue .lib-item-label{color:var(--accent2);}
.lib-item.amber .lib-item-label{color:var(--accent3);}
.lib-item.red .lib-item-label{color:var(--danger);}
.lib-item-value{color:#fff;font-size:13px;font-weight:600;line-height:1.4;}
.lib-item-sub{color:var(--text-muted);font-size:11px;margin-top:3px;}

/* ── ECOSYSTEM AD STRIP ───────────────────────────────── */
.eco-ad-strip{background:linear-gradient(135deg,rgba(0,229,195,0.05),rgba(14,165,233,0.05));border:1px solid var(--border2);border-left:3px solid var(--accent);border-radius:10px;padding:20px 24px;margin-bottom:28px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;}
.eas-left{flex:1;}
.eas-eyebrow{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:2px;text-transform:uppercase;margin-bottom:6px;}
.eas-title{color:#fff;font-size:15px;font-weight:700;margin-bottom:4px;}
.eas-desc{color:var(--text-muted);font-size:12px;}
.eas-right{display:flex;gap:8px;align-items:center;flex-shrink:0;flex-wrap:wrap;}
.eas-btn{font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:9px 16px;border-radius:5px;border:1px solid;transition:0.3s;white-space:nowrap;}
.eas-btn-primary{background:var(--accent);color:#000;border-color:var(--accent);}
.eas-btn-primary:hover{background:#00ffdc;box-shadow:0 0 20px rgba(0,229,195,0.4);}
.eas-btn-ghost{color:var(--text-secondary);border-color:var(--border);}
.eas-btn-ghost:hover{color:#fff;border-color:var(--text-secondary);}

/* ── SECTION LABELS ───────────────────────────────────── */
.section-eyebrow{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:3px;text-transform:uppercase;margin-bottom:20px;display:flex;align-items:center;gap:10px;}
.section-eyebrow::after{content:'';flex:1;height:1px;background:var(--border);}
.section-eyebrow.blue{color:var(--accent2);}
.section-eyebrow.amber{color:var(--accent3);}

/* ── ADSENSE IN-FEED UNIT ─────────────────────────────── */
.ad-unit{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;margin-bottom:28px;position:relative;}
.ad-unit-label{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:2px;text-transform:uppercase;padding:8px 16px;border-bottom:1px solid var(--border);text-align:center;}
.ad-unit-inner{padding:12px;text-align:center;}

/* ── MAIN LAYOUT ──────────────────────────────────────── */
.cdb-main-wrap{max-width:1450px;margin:36px auto;padding:0 24px;display:flex;gap:48px;}
main{flex:1;min-width:0;}

/* ── TOC (Table of Contents) ──────────────────────────── */
.post-toc{background:var(--surface);border:1px solid var(--border);border-left:3px solid var(--accent);border-radius:var(--radius);padding:20px 24px;margin:28px 0;display:none;}
.post-toc.visible{display:block;}
.post-toc-title{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;margin-bottom:14px;}
.post-toc ol{padding-left:20px;}
.post-toc li{margin-bottom:6px;}
.post-toc a{color:var(--text-secondary);font-size:13px;transition:0.2s;}
.post-toc a:hover{color:var(--accent);}

/* ── ARTICLE ──────────────────────────────────────────── */
article{background:var(--card2);padding:46px;border-radius:16px;border:1px solid var(--border);margin-bottom:28px;position:relative;overflow:hidden;}
article::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--border2),transparent);}
.post-meta-line{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:11px;letter-spacing:1px;text-transform:uppercase;margin-bottom:16px;display:flex;flex-wrap:wrap;gap:8px;align-items:center;}
.post-label-tag{color:var(--accent);border:1px solid var(--accent-dim);padding:2px 8px;border-radius:3px;font-size:10px;}
.post-label-tag.red{color:var(--danger);border-color:rgba(239,68,68,0.2);}
.post-label-tag.amber{color:var(--accent3);border-color:rgba(245,158,11,0.2);}
.post-label-tag.blue{color:var(--accent2);border-color:rgba(14,165,233,0.2);}
.post-label-tag.purple{color:var(--accent4);border-color:rgba(139,92,246,0.2);}
.post-title-link{text-decoration:none;display:block;}
.post-title{color:#fff;font-size:clamp(20px,2.5vw,30px);font-weight:900;margin:0 0 22px;font-family:'Outfit',sans-serif;line-height:1.2;}
.post-title-link:hover .post-title{color:var(--accent);}

/* ── POST IMAGE ───────────────────────────────────────── */
.post-hero-image{width:100%;aspect-ratio:16/9;object-fit:cover;border-radius:10px;margin-bottom:28px;border:1px solid var(--border);}
.post-hero-image-wrap{margin:-46px -46px 28px;overflow:hidden;}
.post-hero-image-wrap img{width:100%;height:280px;object-fit:cover;display:block;}

/* ── POST BODY ────────────────────────────────────────── */
.post-body{color:#cbd5e1;font-size:16px;line-height:1.9;}
.post-body h2{color:#fff;font-family:'Outfit',sans-serif;font-size:22px;font-weight:800;margin:36px 0 14px;padding-bottom:10px;border-bottom:1px solid var(--border);}
.post-body h3{color:#fff;font-family:'Outfit',sans-serif;font-size:18px;font-weight:700;margin:28px 0 12px;}
.post-body h4{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:13px;font-weight:700;letter-spacing:1px;text-transform:uppercase;margin:22px 0 10px;}
.post-body p{margin-bottom:18px;}
.post-body ul,.post-body ol{padding-left:24px;margin-bottom:18px;}
.post-body li{margin-bottom:8px;}
.post-body code{background:var(--surface);color:var(--accent);padding:2px 6px;border-radius:3px;font-family:'JetBrains Mono',monospace;font-size:13px;}
.post-body pre{background:var(--surface);border:1px solid var(--border);border-radius:8px;padding:20px;overflow-x:auto;margin:20px 0;}
.post-body pre code{background:none;padding:0;color:#e2e8f0;}
.post-body a{color:var(--accent2);border-bottom:1px solid rgba(14,165,233,0.3);transition:0.2s;}
.post-body a:hover{color:#fff;border-bottom-color:var(--accent2);}
.post-body blockquote{border-left:3px solid var(--accent);background:var(--surface);padding:16px 20px;border-radius:0 8px 8px 0;margin:20px 0;color:var(--text-secondary);font-style:italic;}
.post-body table{width:100%;border-collapse:collapse;margin:20px 0;font-size:14px;}
.post-body th{background:var(--surface);color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:11px;letter-spacing:1px;text-transform:uppercase;padding:10px 14px;border:1px solid var(--border);text-align:left;}
.post-body td{padding:10px 14px;border:1px solid var(--border);color:#cbd5e1;}
.post-body tr:nth-child(even) td{background:rgba(15,21,33,0.5);}

/* ── CVE CALLOUT BOX ──────────────────────────────────── */
.cve-box{background:linear-gradient(135deg,rgba(239,68,68,0.08),rgba(239,68,68,0.03));border:1px solid rgba(239,68,68,0.25);border-left:3px solid var(--danger);border-radius:var(--radius);padding:20px 24px;margin:24px 0;}
.cve-box-header{display:flex;align-items:center;gap:10px;margin-bottom:10px;}
.cve-box-badge{background:var(--danger);color:#fff;font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:900;letter-spacing:1px;padding:3px 10px;border-radius:4px;text-transform:uppercase;}
.cve-box-id{color:#fff;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:14px;}
.cve-box-cvss{color:var(--danger);font-family:'JetBrains Mono',monospace;font-size:12px;font-weight:700;}
.cve-box-desc{color:var(--text-secondary);font-size:14px;line-height:1.7;}

/* ── AUTHOR BOX (E-E-A-T) ─────────────────────────────── */
.author-eeeat-box{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:28px;margin:36px 0;display:flex;gap:20px;align-items:flex-start;}
.author-eeeat-avatar{width:72px;height:72px;border-radius:50%;border:2px solid var(--accent);flex-shrink:0;object-fit:cover;}
.author-eeeat-avatar-placeholder{width:72px;height:72px;border-radius:50%;border:2px solid var(--accent);flex-shrink:0;background:var(--card);display:flex;align-items:center;justify-content:center;font-size:28px;}
.author-eeeat-body{flex:1;min-width:0;}
.author-eeeat-name{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:16px;margin-bottom:2px;}
.author-eeeat-title{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;text-transform:uppercase;margin-bottom:10px;}
.author-eeeat-bio{color:var(--text-secondary);font-size:13px;line-height:1.7;margin-bottom:12px;}
.author-eeeat-creds{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px;}
.author-cred-chip{background:var(--accent-dim);border:1px solid var(--accent-dim);color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:3px 8px;border-radius:3px;}
.author-cred-chip.blue{background:var(--accent2-dim);border-color:var(--accent2-dim);color:var(--accent2);}
.author-eeeat-links{display:flex;gap:8px;}
.author-eeeat-link{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:6px 12px;border:1px solid var(--border);border-radius:4px;transition:0.2s;}
.author-eeeat-link:hover{color:var(--accent);border-color:var(--accent-dim);}

/* ── POST TAGS / LABELS ───────────────────────────────── */
.post-tags-row{display:flex;flex-wrap:wrap;gap:6px;margin:20px 0;padding-top:20px;border-top:1px solid var(--border);}
.post-tag{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;padding:4px 10px;border:1px solid var(--border);border-radius:3px;transition:0.2s;}
.post-tag:hover{color:var(--accent);border-color:var(--accent-dim);background:var(--accent-dim);}

/* ── READ MORE ────────────────────────────────────────── */
.read-more-wrap{margin-top:28px;padding-top:22px;border-top:1px solid var(--border);display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;}
.read-more-btn{display:inline-flex;align-items:center;gap:10px;color:#000!important;background:var(--accent);font-family:'JetBrains Mono',monospace;font-weight:700;font-size:11px;text-transform:uppercase;letter-spacing:1px;text-decoration:none;padding:11px 22px;border-radius:6px;transition:all 0.3s;}
.read-more-btn:hover{background:#00ffdc;box-shadow:0 0 25px rgba(0,229,195,0.5);transform:translateY(-2px);}
.read-more-meta{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;}

/* ── NEWSLETTER INLINE ────────────────────────────────── */
.newsletter-inline{background:linear-gradient(135deg,rgba(0,229,195,0.06),rgba(14,165,233,0.06));border:1px solid var(--border2);border-radius:14px;padding:32px;margin:36px 0;text-align:center;position:relative;overflow:hidden;}
.newsletter-inline::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,var(--accent),var(--accent2));}
.nl-eyebrow{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;margin-bottom:10px;}
.nl-title{color:#fff;font-family:'Outfit',sans-serif;font-size:20px;font-weight:900;margin-bottom:8px;}
.nl-sub{color:var(--text-secondary);font-size:14px;margin-bottom:20px;}
.nl-form{display:flex;gap:10px;max-width:480px;margin:0 auto;flex-wrap:wrap;}
.nl-input{flex:1;background:var(--surface);border:1px solid var(--border);color:#fff;font-family:'Inter',sans-serif;font-size:14px;padding:12px 16px;border-radius:6px;outline:none;min-width:200px;}
.nl-input:focus{border-color:var(--accent);box-shadow:0 0 0 2px var(--accent-dim);}
.nl-input::placeholder{color:var(--text-muted);}
.nl-btn{background:var(--accent);color:#000;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:11px;letter-spacing:1px;text-transform:uppercase;padding:12px 20px;border-radius:6px;border:none;cursor:pointer;transition:0.3s;white-space:nowrap;}
.nl-btn:hover{background:#00ffdc;box-shadow:0 0 20px rgba(0,229,195,0.4);}
.nl-disclaimer{color:var(--text-muted);font-size:11px;margin-top:12px;}

/* ── RELATED POSTS ────────────────────────────────────── */
.related-posts-section{margin-top:40px;padding-top:32px;border-top:2px solid var(--border);}
.related-posts-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:14px;margin-top:16px;}
.related-post-card{background:var(--surface);border:1px solid var(--border);border-radius:10px;overflow:hidden;transition:all 0.3s;display:block;}
.related-post-card:hover{transform:translateY(-4px);border-color:var(--accent);box-shadow:0 8px 30px rgba(0,229,195,0.12);}
.related-post-card img{width:100%;height:130px;object-fit:cover;display:block;}
.related-post-card .rpc-body{padding:12px;}
.related-post-card .rpc-label{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:1px;text-transform:uppercase;margin-bottom:5px;}
.related-post-card .rpc-title{color:#fff;font-size:13px;font-weight:600;line-height:1.4;}

/* ── POST NAVIGATION ──────────────────────────────────── */
.post-nav-wrapper{margin-top:48px;border-top:2px solid var(--border);padding-top:36px;}
.post-nav-eyebrow{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:2px;text-transform:uppercase;text-align:center;margin-bottom:18px;}
.post-nav-grid{display:flex;justify-content:space-between;align-items:stretch;gap:12px;}
.nav-btn{color:var(--accent)!important;font-family:'JetBrains Mono',monospace;font-weight:700;text-transform:uppercase;text-decoration:none;font-size:11px;padding:14px 18px;border:1px solid var(--border);border-radius:6px;background:var(--surface);transition:all 0.3s;display:flex;align-items:center;gap:10px;flex:1;max-width:44%;}
.nav-btn.nav-newer{justify-content:flex-start;}
.nav-btn.nav-older{justify-content:flex-end;text-align:right;}
.nav-btn:hover{background:var(--accent);color:#000!important;border-color:var(--accent);box-shadow:0 0 25px rgba(0,229,195,0.35);transform:translateY(-2px);}
.nav-btn .nav-arrow{font-size:18px;flex-shrink:0;}
.nav-text-block{display:flex;flex-direction:column;gap:3px;overflow:hidden;}
.nav-eyebrow2{font-size:9px;opacity:0.6;letter-spacing:2px;white-space:nowrap;}
.nav-title2{font-size:11px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:220px;}
.nav-hub-btn{color:var(--text-secondary)!important;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:10px;text-transform:uppercase;text-decoration:none;padding:14px 12px;border:1px solid var(--border);border-radius:6px;background:transparent;transition:0.3s;display:flex;align-items:center;justify-content:center;letter-spacing:1px;white-space:nowrap;flex-shrink:0;}
.nav-hub-btn:hover{border-color:var(--text-secondary);color:#fff!important;}
.nav-placeholder{flex:1;max-width:44%;}

/* ── SIDEBAR ──────────────────────────────────────────── */
.matrix-sidebar{width:310px;flex-shrink:0;position:sticky;top:70px;align-self:flex-start;display:flex;flex-direction:column;gap:20px;max-height:calc(100vh - 90px);overflow-y:auto;scrollbar-width:none;}
.matrix-sidebar::-webkit-scrollbar{display:none;}
.sidebar-module{background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:20px;overflow:hidden;position:relative;}
.sidebar-module::before{content:'';position:absolute;top:0;left:0;right:0;height:1px;background:linear-gradient(90deg,transparent,var(--border2),transparent);}
.module-title{color:var(--accent);font-family:'JetBrains Mono',monospace;font-weight:900;font-size:9px;letter-spacing:2px;margin-bottom:14px;border-bottom:1px solid var(--border);padding-bottom:10px;text-transform:uppercase;display:flex;align-items:center;justify-content:space-between;}
.module-title.blue{color:var(--accent2);}
.module-title.amber{color:var(--accent3);}
.module-title.purple{color:var(--accent4);}
.eco-link{display:flex;align-items:center;justify-content:space-between;color:#fff;text-decoration:none;font-size:12px;font-weight:600;margin-bottom:10px;transition:0.2s;padding:7px 10px;border-radius:6px;border:1px solid transparent;}
.eco-link:last-child{margin-bottom:0;}
.eco-link:hover{color:var(--accent);background:var(--accent-dim);border-color:var(--accent-dim);}
.eco-link .el-arrow{font-size:10px;opacity:0.5;transition:0.2s;}
.eco-link:hover .el-arrow{opacity:1;transform:translateX(2px);}
.eco-link .el-badge{font-size:9px;background:var(--accent);color:#000;padding:1px 5px;border-radius:3px;font-family:'JetBrains Mono',monospace;font-weight:700;}
.eco-link .el-badge.blue{background:var(--accent2);}
.eco-link .el-badge.amber{background:var(--accent3);}

/* ── CVE SIDEBAR WIDGET ───────────────────────────────── */
.cve-widget-item{display:flex;align-items:flex-start;gap:10px;padding:10px 0;border-bottom:1px solid var(--border);}
.cve-widget-item:last-child{border-bottom:none;padding-bottom:0;}
.cve-widget-badge{flex-shrink:0;font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:900;padding:3px 7px;border-radius:3px;text-transform:uppercase;}
.cve-widget-badge.crit{background:var(--danger);color:#fff;}
.cve-widget-badge.high{background:var(--accent3);color:#000;}
.cve-widget-badge.med{background:var(--accent2);color:#fff;}
.cve-widget-id{color:#fff;font-family:'JetBrains Mono',monospace;font-size:11px;font-weight:700;margin-bottom:3px;}
.cve-widget-desc{color:var(--text-muted);font-size:11px;line-height:1.4;}

/* ── SIDEBAR AD CARDS ─────────────────────────────────── */
.sidebar-ad-card{border-radius:12px;padding:20px;position:relative;overflow:hidden;text-align:center;}
.sidebar-ad-card.sentinel{background:linear-gradient(135deg,#06080d,#0a1220);border:1px solid rgba(0,229,195,0.25);}
.sidebar-ad-card.tools{background:linear-gradient(135deg,#06080d,#0a1530);border:1px solid rgba(14,165,233,0.25);}
.sidebar-ad-card.api{background:linear-gradient(135deg,#06080d,#120a20);border:1px solid rgba(139,92,246,0.25);}
.sidebar-ad-card.mssp{background:linear-gradient(135deg,#06080d,#1a0d05);border:1px solid rgba(245,158,11,0.25);}
.sac-glow{position:absolute;top:-40px;left:50%;transform:translateX(-50%);width:160px;height:120px;border-radius:50%;pointer-events:none;}
.sac-glow.green{background:radial-gradient(ellipse,rgba(0,229,195,0.15) 0%,transparent 70%);}
.sac-glow.blue{background:radial-gradient(ellipse,rgba(14,165,233,0.15) 0%,transparent 70%);}
.sac-glow.purple{background:radial-gradient(ellipse,rgba(139,92,246,0.15) 0%,transparent 70%);}
.sac-glow.amber{background:radial-gradient(ellipse,rgba(245,158,11,0.15) 0%,transparent 70%);}
.sac-icon{font-size:28px;margin-bottom:10px;display:block;}
.sac-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:14px;margin-bottom:5px;}
.sac-desc{color:var(--text-muted);font-size:11px;line-height:1.5;margin-bottom:14px;}
.sac-features{text-align:left;margin-bottom:14px;}
.sac-feature{color:var(--text-secondary);font-size:11px;padding:3px 0;display:flex;align-items:center;gap:6px;}
.sac-feature::before{content:'✓';color:var(--accent);font-weight:700;font-size:10px;}
.sac-btn{display:block;font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:9px 16px;border-radius:5px;border:1px solid;transition:0.3s;width:100%;text-align:center;}
.sac-btn.green{color:#000;background:var(--accent);border-color:var(--accent);}
.sac-btn.green:hover{background:#00ffdc;box-shadow:0 0 20px rgba(0,229,195,0.4);}
.sac-btn.blue{color:#fff;background:var(--accent2);border-color:var(--accent2);}
.sac-btn.blue:hover{box-shadow:0 0 20px rgba(14,165,233,0.4);}
.sac-btn.purple{color:#fff;background:var(--accent4);border-color:var(--accent4);}
.sac-btn.amber{color:#000;background:var(--accent3);border-color:var(--accent3);}
.sac-btn-ghost{display:block;color:var(--text-secondary);border-color:var(--border);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:8px 16px;border-radius:5px;border:1px solid;transition:0.3s;width:100%;text-align:center;margin-top:8px;}
.sac-btn-ghost:hover{color:#fff;border-color:var(--text-secondary);}

/* ── API STATUS ───────────────────────────────────────── */
.api-status-row{display:flex;align-items:center;justify-content:space-between;padding:7px 0;border-bottom:1px solid var(--border);}
.api-status-row:last-of-type{border-bottom:none;}
.api-status-name{color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;}
.api-status-badge{font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:1px;padding:3px 8px;border-radius:3px;}
.api-status-badge.online{background:rgba(34,197,94,0.15);color:var(--success);}
.api-status-badge.checking{background:rgba(245,158,11,0.15);color:var(--accent3);}
.api-status-badge.offline{background:rgba(239,68,68,0.15);color:var(--danger);}

/* ── THREAT LEVEL GAUGE ───────────────────────────────── */
.threat-gauge{text-align:center;padding:12px 0;}
.threat-gauge-label{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:9px;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px;}
.threat-gauge-level{font-family:'Outfit',sans-serif;font-weight:900;font-size:24px;letter-spacing:2px;text-transform:uppercase;}
.threat-gauge-level.high{color:var(--accent3);}
.threat-gauge-level.critical{color:var(--danger);}
.threat-gauge-level.elevated{color:var(--accent2);}
.threat-gauge-bar{height:6px;background:var(--border);border-radius:3px;overflow:hidden;margin:10px 0 6px;}
.threat-gauge-fill{height:100%;border-radius:3px;background:linear-gradient(90deg,var(--accent),var(--accent3),var(--danger));}
.threat-gauge-sub{color:var(--text-muted);font-size:10px;font-family:'JetBrains Mono',monospace;}

/* ── ENTERPRISE SECTION (below hero) ─────────────────── */
.enterprise-section{background:var(--deep);border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:56px 24px;}
.enterprise-inner{max-width:1200px;margin:0 auto;}
.enterprise-header{text-align:center;margin-bottom:40px;}
.enterprise-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:clamp(22px,3vw,36px);margin-bottom:10px;}
.enterprise-title span{color:var(--accent);}
.enterprise-subtitle{color:var(--text-secondary);font-size:15px;max-width:600px;margin:0 auto;}
.enterprise-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:20px;}
.enterprise-card{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:24px;transition:all 0.3s;position:relative;overflow:hidden;}
.enterprise-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;}
.enterprise-card.green::before{background:var(--accent);}
.enterprise-card.blue::before{background:var(--accent2);}
.enterprise-card.amber::before{background:var(--accent3);}
.enterprise-card.purple::before{background:var(--accent4);}
.enterprise-card:hover{transform:translateY(-4px);box-shadow:var(--glow);}
.enterprise-card.blue:hover{box-shadow:var(--glow2);}
.ec-icon{font-size:32px;margin-bottom:14px;}
.ec-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:800;font-size:17px;margin-bottom:8px;}
.ec-desc{color:var(--text-secondary);font-size:13px;line-height:1.7;margin-bottom:16px;}
.ec-features{display:flex;flex-direction:column;gap:5px;margin-bottom:16px;}
.ec-feature{color:var(--text-muted);font-size:12px;display:flex;align-items:center;gap:8px;}
.ec-feature::before{content:'→';color:var(--accent);font-size:11px;flex-shrink:0;}
.enterprise-card.blue .ec-feature::before{color:var(--accent2);}
.enterprise-card.amber .ec-feature::before{color:var(--accent3);}
.enterprise-card.purple .ec-feature::before{color:var(--accent4);}
.ec-btn{display:block;text-align:center;font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:10px 16px;border-radius:5px;border:1px solid;transition:0.3s;}
.ec-btn.green{color:#000;background:var(--accent);border-color:var(--accent);}
.ec-btn.green:hover{background:#00ffdc;box-shadow:0 0 20px rgba(0,229,195,0.4);}
.ec-btn.blue{color:#fff;background:var(--accent2);border-color:var(--accent2);}
.ec-btn.amber{color:#000;background:var(--accent3);border-color:var(--accent3);}
.ec-btn.purple{color:#fff;background:var(--accent4);border-color:var(--accent4);}

/* ── AI SECURITY SECTION ──────────────────────────────── */
.ai-security-section{background:linear-gradient(135deg,var(--void),#0a081a);border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:56px 24px;}
.ai-security-inner{max-width:1200px;margin:0 auto;}
.ai-security-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin-top:32px;}
.ai-security-card{background:var(--card);border:1px solid var(--border);border-radius:14px;padding:24px;transition:0.3s;}
.ai-security-card:hover{border-color:var(--accent4);box-shadow:0 0 30px rgba(139,92,246,0.12);}
.asc-eyebrow{color:var(--accent4);font-family:'JetBrains Mono',monospace;font-size:9px;font-weight:700;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px;}
.asc-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:800;font-size:16px;margin-bottom:8px;}
.asc-desc{color:var(--text-secondary);font-size:13px;line-height:1.6;margin-bottom:14px;}
.asc-link{color:var(--accent4);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;}
.asc-link:hover{color:#fff;}

/* ── MSSP SECTION ─────────────────────────────────────── */
.mssp-section{background:var(--deep);border-top:1px solid var(--border);border-bottom:1px solid var(--border);padding:56px 24px;}
.mssp-inner{max-width:1200px;margin:0 auto;}
.mssp-hero{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center;margin-top:32px;}
.mssp-content-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:clamp(20px,2.5vw,32px);margin-bottom:12px;line-height:1.2;}
.mssp-content-title span{color:var(--accent3);}
.mssp-content-desc{color:var(--text-secondary);font-size:14px;line-height:1.8;margin-bottom:20px;}
.mssp-services-list{display:flex;flex-direction:column;gap:10px;margin-bottom:24px;}
.mssp-service-item{display:flex;align-items:center;gap:12px;padding:12px 16px;background:var(--surface);border:1px solid var(--border);border-radius:8px;}
.mssp-service-icon{font-size:18px;flex-shrink:0;}
.mssp-service-name{color:#fff;font-size:13px;font-weight:600;}
.mssp-service-desc{color:var(--text-muted);font-size:11px;}
.mssp-cta-row{display:flex;gap:10px;flex-wrap:wrap;}
.mssp-btn-primary{background:var(--accent3);color:#000;font-family:'JetBrains Mono',monospace;font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:13px 22px;border-radius:6px;border:1px solid var(--accent3);transition:0.3s;}
.mssp-btn-primary:hover{box-shadow:0 0 25px rgba(245,158,11,0.4);transform:translateY(-2px);}
.mssp-btn-ghost{color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:11px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:13px 22px;border-radius:6px;border:1px solid var(--border);transition:0.3s;}
.mssp-btn-ghost:hover{color:#fff;border-color:var(--text-secondary);}
.mssp-stats-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;}
.mssp-stat-card{background:var(--card);border:1px solid var(--border);border-radius:10px;padding:20px;text-align:center;}
.mssp-stat-num{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:28px;margin-bottom:4px;}
.mssp-stat-label{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;text-transform:uppercase;}

/* ── DETECTION ENGINEERING SECTION ───────────────────── */
.detection-section{background:var(--void);padding:56px 24px;}
.detection-inner{max-width:1200px;margin:0 auto;}
.detection-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-top:28px;}
.detection-card{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:20px;transition:0.3s;text-align:center;}
.detection-card:hover{border-color:var(--accent2);transform:translateY(-3px);box-shadow:var(--glow2);}
.dc-icon{font-size:32px;margin-bottom:12px;}
.dc-count{color:var(--accent2);font-family:'Outfit',sans-serif;font-weight:900;font-size:28px;margin-bottom:4px;}
.dc-label{color:#fff;font-size:13px;font-weight:600;margin-bottom:6px;}
.dc-sub{color:var(--text-muted);font-size:11px;}

/* ── FOOTER ───────────────────────────────────────────── */
.cdb-footer{background:var(--deep);border-top:2px solid var(--border);margin-top:60px;}
.footer-eco-banner{background:linear-gradient(135deg,rgba(0,229,195,0.06),rgba(14,165,233,0.04));border-bottom:1px solid var(--border);padding:40px 24px;}
.feb-inner{max-width:1200px;margin:0 auto;display:flex;justify-content:space-between;align-items:center;gap:24px;flex-wrap:wrap;}
.feb-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:22px;margin-bottom:8px;}
.feb-title span{color:var(--accent);}
.feb-sub{color:var(--text-secondary);font-size:14px;margin-bottom:16px;}
.feb-platforms{display:flex;flex-wrap:wrap;gap:8px;}
.feb-platform-chip{color:var(--text-secondary);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:6px 12px;border:1px solid var(--border);border-radius:4px;transition:0.2s;}
.feb-platform-chip:hover{color:var(--accent);border-color:var(--accent-dim);background:var(--accent-dim);}
.feb-cta-col{display:flex;flex-direction:column;gap:8px;flex-shrink:0;}
.feb-btn{font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;text-transform:uppercase;padding:11px 20px;border-radius:5px;border:1px solid;transition:0.3s;text-align:center;white-space:nowrap;}
.feb-btn-primary{background:var(--accent);color:#000;border-color:var(--accent);}
.feb-btn-primary:hover{background:#00ffdc;box-shadow:0 0 20px rgba(0,229,195,0.4);}
.feb-btn-secondary{background:transparent;color:var(--accent3);border-color:rgba(245,158,11,0.3);}
.feb-btn-secondary:hover{background:rgba(245,158,11,0.06);}

/* ── FOOTER NEWSLETTER STRIP ──────────────────────────── */
.footer-nl-strip{background:linear-gradient(135deg,rgba(0,229,195,0.04),rgba(14,165,233,0.04));border-bottom:1px solid var(--border);padding:32px 24px;}
.footer-nl-inner{max-width:900px;margin:0 auto;text-align:center;}
.fnl-title{color:#fff;font-family:'Outfit',sans-serif;font-weight:800;font-size:18px;margin-bottom:6px;}
.fnl-sub{color:var(--text-secondary);font-size:13px;margin-bottom:18px;}
.fnl-form{display:flex;gap:10px;max-width:480px;margin:0 auto;flex-wrap:wrap;justify-content:center;}
.fnl-input{flex:1;min-width:200px;background:var(--surface);border:1px solid var(--border);color:#fff;font-family:'Inter',sans-serif;font-size:14px;padding:11px 16px;border-radius:6px;outline:none;}
.fnl-input:focus{border-color:var(--accent);}
.fnl-btn{background:var(--accent);color:#000;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:11px;letter-spacing:1px;text-transform:uppercase;padding:11px 20px;border-radius:6px;border:none;cursor:pointer;transition:0.3s;}
.fnl-btn:hover{background:#00ffdc;}

/* ── FOOTER GRID ──────────────────────────────────────── */
.footer-grid{max-width:1200px;margin:0 auto;padding:48px 24px;display:grid;grid-template-columns:2fr 1fr 1fr 1fr 1fr;gap:32px;}
.footer-brand-name{color:#fff;font-family:'Outfit',sans-serif;font-weight:900;font-size:20px;letter-spacing:1px;margin-bottom:4px;}
.footer-brand-tagline{color:var(--accent);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:2px;text-transform:uppercase;margin-bottom:14px;}
.footer-brand-desc{color:var(--text-muted);font-size:12px;line-height:1.7;margin-bottom:16px;}
.footer-social-row{display:flex;flex-wrap:wrap;gap:8px;}
.footer-social-link{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;font-weight:700;letter-spacing:1px;padding:5px 10px;border:1px solid var(--border);border-radius:4px;transition:0.2s;}
.footer-social-link:hover{color:var(--accent);border-color:var(--accent-dim);}
.footer-col-title{color:#fff;font-family:'JetBrains Mono',monospace;font-weight:700;font-size:10px;letter-spacing:2px;text-transform:uppercase;margin-bottom:14px;padding-bottom:10px;border-bottom:1px solid var(--border);}
.footer-link{display:block;color:var(--text-muted);font-size:12px;margin-bottom:8px;transition:0.2s;padding:3px 0;}
.footer-link:hover{color:var(--accent);}
.footer-bottom{background:var(--void);border-top:1px solid var(--border);padding:16px 24px;text-align:center;}
.footer-bottom-inner{max-width:1200px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;}
.footer-copyright{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;letter-spacing:1px;}
.footer-bottom-links{display:flex;gap:16px;}
.footer-bottom-link{color:var(--text-muted);font-family:'JetBrains Mono',monospace;font-size:10px;transition:0.2s;}
.footer-bottom-link:hover{color:var(--accent);}

/* ── UTILITY ──────────────────────────────────────────── */
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0;}
.truncate{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}

/* ── RESPONSIVE ───────────────────────────────────────── */
@media(max-width:1200px){
  .footer-grid{grid-template-columns:1fr 1fr 1fr;}.footer-brand{grid-column:1/-1;}
  .ai-security-grid{grid-template-columns:1fr;}
  .mssp-hero{grid-template-columns:1fr;}
}
@media(max-width:900px){
  .cdb-main-wrap{flex-direction:column;gap:28px;}
  .matrix-sidebar{width:100%;position:static;max-height:none;}
  .nav-links{display:none;}
  .nav-cta-group .nav-link:not(.highlight){display:none;}
  .nav-hamburger{display:flex;}
  article{padding:28px 20px;}
  .post-hero-image-wrap{margin:-28px -20px 20px;}
  .author-eeeat-box{flex-direction:column;align-items:center;text-align:center;}
  .author-eeeat-links{justify-content:center;}
  .hero-stats-row{gap:20px;}
  .post-nav-grid{flex-direction:column;}
  .nav-btn{max-width:100%;}
  .feb-inner{flex-direction:column;text-align:center;}
  .feb-platforms{justify-content:center;}
  .feb-cta-col{flex-direction:row;flex-wrap:wrap;justify-content:center;}
}
@media(max-width:600px){
  .footer-grid{grid-template-columns:1fr 1fr;}
  .platform-cards{grid-template-columns:1fr 1fr;}
  .hero-cta-row{flex-direction:column;align-items:stretch;}
  .hero-btn{justify-content:center;}
  .nl-form{flex-direction:column;}
  .mssp-stats-grid{grid-template-columns:1fr 1fr;}
}

/* ── PRINT STYLES ─────────────────────────────────────── */
@media print{
  .cdb-ticker,.cdb-topnav,.mobile-menu,.matrix-sidebar,.cdb-footer,.eco-ad-strip,.newsletter-inline,.ad-unit{display:none!important;}
  body{background:#fff;color:#000;}
  article{border:none;padding:0;}
  .post-title,.post-body h2,.post-body h3{color:#000;}
  .post-body{color:#333;}
}

